-- Expand CMS keys for editable site content (marquee, events, intros)

on conflict (key) do nothing;

-- Extend director_message with full body if missing
update public.site_content
set value = value || '{"body":"The Department of Holistic Education (DHE) is a national educational transformation platform dedicated to building Bharat as a global knowledge leader through value-based education, innovation, research, entrepreneurship, and holistic human development aligned with NEP 2020.\n\nInspired by the transformative educational philosophy of Vidya Bharati, DHE advances holistic education, skill development, leadership, and Bharatiya values through programs, cells, and national initiatives such as Shiksha Mahakumbh."}'::jsonb
where key = 'director_message' and not (value ? 'body');
